esqlQuery.esql:
// Alert when today's total cost (USD) exceeds 1.5 times the average daily cost of the previous
// days in the rule window, and is above 10 USD.
// MAX deduplicates re-polled documents of the same day; the dedup key includes all supported
// dimension fields (unused ones are null).
// Today's total grows while the day is polled, so the alert can appear later in the day.
// The alert ID is the current day, so there is one alert per day.
// Tuning: 1.5 = multiple of the baseline, 10 = minimum cost in USD.
FROM metrics-openrouter.usage-*
| WHERE openrouter.usage.total_usage IS NOT NULL
| STATS _v = MAX(openrouter.usage.total_usage) BY @timestamp, openrouter.usage.model, openrouter.usage.provider, openrouter.usage.variant, openrouter.usage.api_key_id, openrouter.usage.workspace, openrouter.usage.app, openrouter.usage.user
| STATS day_cost = SUM(_v) BY day = @timestamp
| EVAL is_today = day >= DATE_TRUNC(1 day, NOW())
| STATS today_cost = SUM(day_cost) WHERE is_today, baseline_cost = AVG(day_cost) WHERE NOT is_today BY today = DATE_TRUNC(1 day, NOW())
| WHERE today_cost > baseline_cost * 1.5 AND today_cost > 10
| KEEP today, today_cost, baseline_cost
